import "fmt"

// Index는 comparable 인터페이스를 만족하는 모든 타입 슬라이스에서 x의 위치를 찾습니다.
func Index[T comparable](s []T, x T) int {
	for i, v := range s {
		if v == x {
			return i
		}
	}
	return -1
}

func main() {
	si := []int{10, 20, 15, -10}
	fmt.Println("20의 인덱스:", Index(si, 20))

	ss := []string{"apple", "banana", "cherry"}
	fmt.Println("banana의 인덱스:", Index(ss, "banana"))
}

package main

import "fmt"

func sum(s []int, c chan int) {
	total := 0
	for _, v := range s {
		total += v
	}
	c <- total // 결과를 채널에 전송
}

func main() {
	s := []int{7, 2, 8, -9, 4, 0}
	c := make(chan int)

	go sum(s[:len(s)/2], c)
	go sum(s[len(s)/2:], c)

	x, y := <-c, <-c // 채널로부터 두 결과를 수신

	fmt.Println("x:", x, "y:", y, "합계:", x+y)
}

